sys_trigger.script:
// SN Transform Map Health Auditor — Daily Health Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// Scheduled job: runs daily at 03:00 UTC, scans all transform maps,
// computes health scores, and generates alerts for scores below threshold.

(function() {
    try {
        var engine = new x_snc_tmh.TransformMapHealthEngine();
        var resultId = engine.scanAll();

        if (resultId) {
            gs.info('TMH Daily Scan completed. Summary result: ' + resultId);
        } else {
            gs.warn('TMH Daily Scan completed but produced no results. No transform maps found or scan failed.');
        }
    } catch (e) {
        gs.error('TMH Daily Scan failed: ' + e.message);
    }
})();
